sys_ui_page.client_script:
// Function to toggle visibility of child checkboxes

//var getRecordSysID = GlideModal.get().getPreference('sys_id');
//var getTableName = GlideModal.get().getPreference('table_name');

// Function to show/hide child options based on dropdown selection
function showHideChildOptions(selectedValue) {
    // Get all child containers
    var allChildContainers = document.querySelectorAll('[id$="_children_container"]');

    // Hide all child containers first and uncheck their checkboxes
    allChildContainers.forEach(function(container) {
        container.style.display = 'none';
        var checkboxes = container.querySelectorAll('input[type="checkbox"]');
        checkboxes.forEach(function(chk) {
            chk.checked = false;
        });
    });

    // Show the relevant child container based on the selected value
    if (selectedValue) { // Only if a valid option (not "-- None --") is selected
        var targetContainerId = selectedValue + '_children_container';
        var targetContainer = document.getElementById(targetContainerId);
        if (targetContainer) {
            targetContainer.style.display = 'block';
        }
    }
}


function saveOptions() {
    var options = {};
    // Get the selected parent option from the dropdown
    var parentSelect = document.getElementById('parent_option_select');
    var selectedParentValue = parentSelect.value;

    // Add the selected parent option to the options object if it's not "-- None --"
    if (selectedParentValue) {
        options[selectedParentValue] = true; // Mark the selected parent as true
    }

    // Select all individual checkbox inputs (excluding the parent dropdown itself)
    // We target inputs by type checkbox, but specifically in the containers that hold them.
    // This will pick up: trade_date_1, trade_date_2, settlement_date_1, settlement_date_2
    // AND all the individual checkboxes in the right column.
    var checkboxes = document.querySelectorAll(
        '#trade_date_children_container input[type="checkbox"], ' +
        '#settlement_date_children_container input[type="checkbox"], ' +
        'div[style*="flex: 0 0 200px"] ul input[type="checkbox"]' // Targets checkboxes in the right column
    );

    checkboxes.forEach(function(checkbox) {
        // Only add checkbox to options if it's checked or it's a child of the selected parent
        // If a child is hidden, its value would be false anyway, so just add if checked.
        if (checkbox.checked) {
            options[checkbox.name] = true;
        } else {
            // Important: If a checkbox is not checked, explicitly set to false to ensure it's recorded
            // This prevents previously checked but now unchecked options from lingering in the description.
            options[checkbox.name] = false;
        }
    });

   var getRecordSysID = GlideModal.get().getPreference('sys_id');
   var getTableName = GlideModal.get().getPreference('table_name');

    var ga = new GlideAjax('x_938076_now_utils.OptionProcessorAjax');
    ga.addParam('sysparm_name', 'updateSelectedOptions');
    ga.addParam('sysparm_record_sys_id', getRecordSysID);
    ga.addParam('sysparm_table_name', getTableName);
    ga.addParam('sysparm_options_data', JSON.stringify(options));
    ga.getXML(function(response) {
        var answer = response.responseXML.documentElement.getAttribute("answer");
        if (answer == 'success') {
            // alert('Options saved successfully!'); // Re-enable for debugging if needed
            GlideModal.get().destroy();
            parent.location.reload(); // Reload the parent form
        } else {
            alert('Error saving options: ' + answer);
        }
    });

    return false; // Prevents the modal from closing immediately after clicking 'Save'
}

// Initial call to hide all children when the page loads (in case of a refresh)
// Wrap in addLoadEvent for proper DOM readiness.
addLoadEvent(function() {
    showHideChildOptions(document.getElementById('parent_option_select').value);
});

sys_ui_page.processing_script:
// Ensure this script is as minimal as possible to allow RP.getWindowProperties() to populate
// correctly from the dialog preferences.

// Do NOT use template.print(template.apply(...)); when using RP.getWindowProperties()
// to populate Jelly variables directly into the HTML like this.
// Setting 'answer' to something or leaving it blank is often sufficient.
answer = ''; // Or answer = true;
